import java.util.Scanner;

public class MovieTicket {
    private String title;
    private int seats;
    private char seatType;
    private double amount;

    public MovieTicket() {
        title = "";
        seats = 0;
        seatType = 'S';
        amount = 0.0;
    }

    public void accept() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Movie Title: ");
        title = in.nextLine();
        System.out.print("Enter Seats to Book: ");
        seats = in.nextInt();
        System.out.print("Enter Tier ('S' Silver, 'G' Gold, 'P' Platinum): ");
        seatType = in.next().toUpperCase().charAt(0);
    }

    public void calculate() {
        double rate;
        switch (seatType) {
            case 'S': rate = 180.0; break;
            case 'G': rate = 260.0; break;
            case 'P': rate = 380.0; break;
            default:
                rate = 180.0;
                System.out.println("Invalid tier code. Applied Silver rate.");
        }

        double gross = seats * rate;
        double discount = (seats > 5) ? (0.10 * gross) : 0.0;
        amount = gross - discount;
    }

    public void display() {
        System.out.println("\n============== CINEMA INVOICE ==============");
        System.out.println("Movie Title    : " + title);
        System.out.println("Tickets Booked : " + seats);
        System.out.println("Tier Category  : " + seatType);
        System.out.println("Final Amount   : Rs. " + amount);
        System.out.println("============================================");
    }

    public static void main(String[] args) {
        MovieTicket ticket = new MovieTicket();
        ticket.accept();
        ticket.calculate();
        ticket.display();
    }
}
```

