import java.util.Scanner;

public class SelectionSortDescending {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 10;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " integers for Descending Selection Sort:");
        for (int i = 0; i < N; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.print("\nOriginal Array: ");
        for (int v : arr) System.out.print(v + " ");
        System.out.println();

        for (int i = 0; i < N - 1; i++) {
            int maxIdx = i;
            for (int j = i + 1; j < N; j++) {
                if (arr[j] > arr[maxIdx]) {
                    maxIdx = j;
                }
            }
            if (maxIdx != i) {
                int temp = arr[i];
                arr[i] = arr[maxIdx];
                arr[maxIdx] = temp;
            }
        }

        System.out.print("Sorted Array (Descending): ");
        for (int v : arr) System.out.print(v + " ");
        System.out.println();
    }
}
```

