import java.util.Scanner;

public class VowelCyclicShift {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter a string:");
        String text = in.nextLine();

        StringBuilder sb = new StringBuilder();
        String vowelsUpper = "AEIOU";
        String vowelsLower = "aeiou";

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);

            int uIdx = vowelsUpper.indexOf(ch);
            int lIdx = vowelsLower.indexOf(ch);

            if (uIdx != -1) {
                sb.append(vowelsUpper.charAt((uIdx + 1) % 5));
            } else if (lIdx != -1) {
                sb.append(vowelsLower.charAt((lIdx + 1) % 5));
            } else {
                sb.append(ch);
            }
        }

        System.out.println("\nOriginal String   : " + text);
        System.out.println("Transformed String: " + sb.toString());
    }
}
```

