import java.util.Scanner;

public class DiagonalSumsEquality {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter square matrix order N (3 to 6): ");
        int n = in.nextInt();

        int[][] mat = new int[n][n];
        System.out.println("Enter " + (n * n) + " elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        int primarySum = 0;
        int secondarySum = 0;

        for (int i = 0; i < n; i++) {
            primarySum += mat[i][i];
            secondarySum += mat[i][n - 1 - i];
        }

        System.out.println("\nPrimary Diagonal Sum   = " + primarySum);
        System.out.println("Secondary Diagonal Sum = " + secondarySum);

        if (primarySum == secondarySum) {
            System.out.println("The diagonal sums are EQUAL (" + primarySum + ").");
        } else {
            System.out.println("The diagonal sums are NOT equal.");
        }
    }
}
```

