import java.util.Scanner;

public class MenuPatternHarmonic {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("========== UTILITY MENU ==========");
        System.out.println("1. Alphabet Repeating Triangle");
        System.out.println("2. Fractional Series Sum: 1/2 + 2/3 + ... + n/(n+1)");
        System.out.print("Enter choice (1 or 2): ");
        int choice = sc.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter number of rows (1 to 26): ");
                int rows = sc.nextInt();
                if (rows < 1 || rows > 26) {
                    System.out.println("Rows must be between 1 and 26.");
                    break;
                }
                for (int i = 0; i < rows; i++) {
                    char ch = (char) ('A' + i);
                    for (int j = 0; j <= i; j++) {
                        System.out.print(ch + " ");
                    }
                    System.out.println();
                }
                break;

            case 2:
                System.out.print("Enter number of terms n: ");
                int n = sc.nextInt();
                if (n <= 0) {
                    System.out.println("Terms must be > 0.");
                    break;
                }
                double sum = 0.0;
                for (int i = 1; i <= n; i++) {
                    sum += (double) i / (i + 1);
                }
                System.out.printf("Sum of series S = %.4f\n", sum);
                break;

            default:
                System.out.println("Invalid Option.");
        }
    }
}
```

